draw:
var omega = Math.sqrt(p.k / p.mass);
var T = 2 * Math.PI / omega;
var A = p.amplitude;
var eqX = W * 0.46, wallX = W * 0.06, scale = W * 0.26, midY = H * 0.24;
var x = A * Math.cos(omega * t);
var v = -A * omega * Math.sin(omega * t);
var massX = eqX + x * scale;
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 2;

ctx.fillStyle = C.faint;
ctx.fillRect(wallX - 8, midY - 40, 8, 80);

ctx.strokeStyle = C.accent;
ctx.beginPath();
ctx.moveTo(wallX, midY);
var i, sx, sy;
for (i = 1; i <= 14; i++) {
  sx = wallX + (massX - 15 - wallX) * i / 14;
  sy = midY + (i % 2 === 0 ? -9 : 9) * (i === 14 ? 0 : 1);
  ctx.lineTo(sx, sy);
}
ctx.lineTo(massX - 15, midY);
ctx.stroke();

ctx.strokeStyle = C.rule;
ctx.setLineDash([3, 5]);
ctx.beginPath(); ctx.moveTo(eqX, midY - 46); ctx.lineTo(eqX, midY + 34); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.faint;
ctx.fillText("x = 0", eqX - 14, midY + 48);

ctx.fillStyle = C.figure;
ctx.fillRect(massX - 15, midY - 15, 30, 30);

ctx.strokeStyle = C.accent;
ctx.fillStyle = C.accent;
var ax = -omega * omega * x * scale * 0.06;
if (Math.abs(ax) > 3) {
  var dir = ax > 0 ? 1 : -1;
  var tipX = massX + ax;
  ctx.beginPath();
  ctx.moveTo(massX, midY - 26);
  ctx.lineTo(tipX, midY - 26);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(tipX, midY - 26);
  ctx.lineTo(tipX - 6 * dir, midY - 30);
  ctx.lineTo(tipX - 6 * dir, midY - 22);
  ctx.closePath(); ctx.fill();
  ctx.fillText("a", (massX + tipX) / 2 - 3, midY - 32);
}

var gy = H * 0.74, gh = H * 0.20;
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(40, gy); ctx.lineTo(W - 12, gy); ctx.stroke();
ctx.fillStyle = C.faint;
ctx.fillText("time", W - 42, gy + 16);
ctx.fillStyle = C.figure;
ctx.fillText("x", 20, gy - gh + 4);
ctx.fillStyle = C.accent;
ctx.fillText("v", 20, gy + 14);

var span = 2.4;
var n = 160;
ctx.lineWidth = 1.6;
ctx.strokeStyle = C.figure;
ctx.beginPath();
for (i = 0; i < n; i++) {
  var tt = t - span * (n - 1 - i) / (n - 1);
  var px = 40 + (W - 52) * i / (n - 1);
  var py = gy - Math.cos(omega * tt) * gh;
  if (i === 0) { ctx.moveTo(px, py); } else { ctx.lineTo(px, py); }
}
ctx.stroke();
ctx.strokeStyle = C.accent;
ctx.beginPath();
for (i = 0; i < n; i++) {
  var tt2 = t - span * (n - 1 - i) / (n - 1);
  var px2 = 40 + (W - 52) * i / (n - 1);
  var py2 = gy + Math.sin(omega * tt2) * gh * 0.7;
  if (i === 0) { ctx.moveTo(px2, py2); } else { ctx.lineTo(px2, py2); }
}
ctx.stroke();

out.note = "omega = " + omega.toFixed(2) + " rad/s, T = " + T.toFixed(3) + " s, f = " + (1 / T).toFixed(2) + " Hz, vmax = " + (A * omega).toFixed(2) + " m/s, amax = " + (A * omega * omega).toFixed(1) + " m/s^2";

var omega = Math.sqrt(p.k / p.mass);
var A = p.amplitude;
var x = A * Math.cos(omega * t);
var v = -A * omega * Math.sin(omega * t);
var E = 0.5 * p.k * A * A;
var U = 0.5 * p.k * x * x;
var K = E - U;
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1.5;

var cx = W * 0.36, baseY = H * 0.84, top = H * 0.14;
var xs = (W * 0.30) / A;
var ys = (baseY - top) / E;

ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.moveTo(cx - W * 0.32, baseY); ctx.lineTo(cx + W * 0.32, baseY); ctx.stroke();
ctx.beginPath(); ctx.moveTo(cx, baseY + 6); ctx.lineTo(cx, top - 6); ctx.stroke();
ctx.fillStyle = C.faint;
ctx.fillText("x", cx + W * 0.30, baseY + 16);
ctx.fillText("energy", cx + 6, top - 10);

ctx.strokeStyle = C.figure;
ctx.lineWidth = 2;
ctx.beginPath();
var i;
for (i = 0; i <= 80; i++) {
  var xx = -A * 1.05 + (2.1 * A) * i / 80;
  var px = cx + xx * xs;
  var py = baseY - 0.5 * p.k * xx * xx * ys;
  if (i === 0) { ctx.moveTo(px, py); } else { ctx.lineTo(px, py); }
}
ctx.stroke();
ctx.fillStyle = C.figure;
ctx.fillText("U = kx^2 / 2", cx + A * 1.0 * xs - 60, baseY - E * ys - 10);

var eY = baseY - E * ys;
ctx.strokeStyle = C.accent;
ctx.lineWidth = 1.5;
ctx.setLineDash([4, 4]);
ctx.beginPath(); ctx.moveTo(cx - A * xs, eY); ctx.lineTo(cx + A * xs, eY); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.accent;
ctx.fillText("total E", cx - A * xs - 4, eY - 8);

var bx = cx + x * xs;
var by = baseY - U * ys;
ctx.strokeStyle = C.accent;
ctx.lineWidth = 3;
ctx.beginPath(); ctx.moveTo(bx, by); ctx.lineTo(bx, eY); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.beginPath(); ctx.arc(bx, by, 5, 0, 6.2832); ctx.fill();
ctx.fillStyle = C.accent;
ctx.fillText("K", bx + 6, (by + eY) / 2 + 4);

ctx.strokeStyle = C.rule;
ctx.lineWidth = 1;
ctx.setLineDash([2, 4]);
ctx.beginPath(); ctx.moveTo(bx, by); ctx.lineTo(bx, baseY); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.figure;
ctx.fillText("U", bx + 6, (by + baseY) / 2 + 4);

var barX = W * 0.80, barW = W * 0.10, barTop = top, barBot = baseY;
var full = barBot - barTop;
ctx.strokeStyle = C.rule;
ctx.strokeRect(barX, barTop, barW, full);
var hK = full * (K / E);
ctx.fillStyle = C.accent;
ctx.fillRect(barX, barBot - hK, barW, hK);
ctx.fillStyle = C.figure;
ctx.fillRect(barX, barTop, barW, full - hK);
ctx.fillStyle = C.faint;
ctx.fillText("K", barX + barW + 6, barBot - hK / 2);
ctx.fillText("U", barX + barW + 6, barTop + (full - hK) / 2);

out.note = "x = " + x.toFixed(3) + " m, v = " + Math.abs(v).toFixed(2) + " m/s, K = " + K.toFixed(3) + " J, U = " + U.toFixed(3) + " J, total = " + E.toFixed(3) + " J";

var g = 9.8;
var sag = p.mass * g / p.k;
var omega = Math.sqrt(p.k / p.mass);
var A = p.amplitude;
var u = A * Math.cos(omega * t);
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 2;

var topY = H * 0.12;
var scale = (H * 0.52) / Math.max(sag + A, 0.02);
if (scale > 900) { scale = 900; }
var natural = H * 0.34;
var colX = [W * 0.20, W * 0.50, W * 0.80];

function coil(cx, y0, y1) {
  ctx.strokeStyle = C.accent;
  ctx.beginPath();
  ctx.moveTo(cx, y0);
  var i;
  for (i = 1; i <= 12; i++) {
    var yy = y0 + (y1 - y0) * i / 12;
    var xx = cx + (i % 2 === 0 ? -10 : 10) * (i === 12 ? 0 : 1);
    ctx.lineTo(xx, yy);
  }
  ctx.lineTo(cx, y1);
  ctx.stroke();
}

ctx.strokeStyle = C.faint;
ctx.lineWidth = 3;
ctx.beginPath(); ctx.moveTo(W * 0.08, topY); ctx.lineTo(W * 0.92, topY); ctx.stroke();
ctx.lineWidth = 2;
ctx.fillStyle = C.faint;
ctx.fillText("ceiling", W * 0.08, topY - 8);

var labels = ["no load", "hanging at rest", "oscillating"];
var ends = [natural, natural + sag * scale, natural + (sag + u) * scale];
var i;
for (i = 0; i < 3; i++) {
  coil(colX[i], topY, ends[i]);
  if (i > 0) {
    ctx.fillStyle = C.figure;
    ctx.fillRect(colX[i] - 16, ends[i], 32, 24);
  }
  ctx.fillStyle = C.faint;
  ctx.fillText(labels[i], colX[i] - 34, H * 0.95);
}

ctx.strokeStyle = C.rule;
ctx.setLineDash([3, 4]);
ctx.beginPath(); ctx.moveTo(colX[0] - 20, natural); ctx.lineTo(colX[2] + 30, natural); ctx.stroke();
var eqY = natural + sag * scale;
ctx.beginPath(); ctx.moveTo(colX[1] - 20, eqY); ctx.lineTo(colX[2] + 30, eqY); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.faint;
ctx.fillText("natural length", colX[0] - 20, natural - 6);
ctx.fillStyle = C.accent;
ctx.fillText("equilibrium", colX[2] - 10, eqY - 6);

ctx.strokeStyle = C.accent;
ctx.beginPath();
ctx.moveTo(colX[1] + 44, natural);
ctx.lineTo(colX[1] + 44, eqY);
ctx.stroke();
ctx.fillStyle = C.accent;
ctx.fillText("mg/k", colX[1] + 48, (natural + eqY) / 2 + 4);

out.note = "sag mg/k = " + sag.toFixed(4) + " m, omega = " + omega.toFixed(2) + " rad/s, T = " + (2 * Math.PI / omega).toFixed(3) + " s, amax = " + (A * omega * omega).toFixed(2) + " m/s^2 (contact needs amax below 9.8)";

var kp = p.k1 + p.k2;
var ks = (p.k1 * p.k2) / (p.k1 + p.k2);
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 2;

function coilH(x0, x1, y, turns) {
  ctx.strokeStyle = C.accent;
  ctx.beginPath();
  ctx.moveTo(x0, y);
  var i;
  for (i = 1; i <= turns; i++) {
    var xx = x0 + (x1 - x0) * i / turns;
    var yy = y + (i % 2 === 0 ? -8 : 8) * (i === turns ? 0 : 1);
    ctx.lineTo(xx, yy);
  }
  ctx.lineTo(x1, y);
  ctx.stroke();
}

var leftW = W * 0.46;
var wallA = W * 0.05, massA = W * 0.36;
var yA1 = H * 0.22, yA2 = H * 0.40;
ctx.fillStyle = C.faint;
ctx.fillRect(wallA - 8, yA1 - 26, 8, (yA2 - yA1) + 52);
coilH(wallA, massA, yA1, 10);
coilH(wallA, massA, yA2, 10);
ctx.fillStyle = C.figure;
ctx.fillRect(massA, yA1 - 14, 26, (yA2 - yA1) + 28);
ctx.fillStyle = C.ink;
ctx.fillText("k1", (wallA + massA) / 2 - 6, yA1 - 16);
ctx.fillText("k2", (wallA + massA) / 2 - 6, yA2 + 26);
ctx.fillStyle = C.faint;
ctx.fillText("parallel: same stretch, forces add", wallA, H * 0.60);
ctx.fillStyle = C.accent;
ctx.fillText("k = k1 + k2 = " + kp.toFixed(0) + " N/m", wallA, H * 0.72);

var wallB = W * 0.56, midB = W * 0.74, massB = W * 0.90;
var yB = H * 0.30;
ctx.fillStyle = C.faint;
ctx.fillRect(wallB - 8, yB - 26, 8, 52);
coilH(wallB, midB, yB, 8);
coilH(midB, massB - 4, yB, 8);
ctx.fillStyle = C.rule;
ctx.beginPath(); ctx.arc(midB, yB, 4, 0, 6.2832); ctx.fill();
ctx.fillStyle = C.figure;
ctx.fillRect(massB - 4, yB - 16, 24, 32);
ctx.fillStyle = C.ink;
ctx.fillText("k1", (wallB + midB) / 2 - 6, yB - 18);
ctx.fillText("k2", (midB + massB) / 2 - 6, yB - 18);
ctx.fillStyle = C.faint;
ctx.fillText("series: same force, stretches add", wallB, H * 0.60);
ctx.fillStyle = C.accent;
ctx.fillText("1/k = 1/k1 + 1/k2 -> " + ks.toFixed(1) + " N/m", wallB, H * 0.72);

ctx.strokeStyle = C.rule;
ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(W * 0.51, H * 0.10); ctx.lineTo(W * 0.51, H * 0.80); ctx.stroke();

out.note = "parallel k = " + kp.toFixed(0) + " N/m, series k = " + ks.toFixed(1) + " N/m (series is softer than either spring)";
